namespace Lastlight.Core;
public sealed partial class World
{
 public void ValidateSolar(Definitions d)
 {
  var s=Solar;if(s==null||!s.Initialized||s.RandomState==0||s.NextId<1||!SolarModes.Contains(s.Mode)||!Directors.Contains(s.Director)||s.Stage is <0 or >4||s.SeasonDays is <2 or >60||s.Luminosity is <0 or >100||s.Instability is <0 or >100||s.StartedAt<0||s.StartedAt>Tick||s.NextBoundary<0||s.LastDay<0||s.LastDay>Tick/TicksPerDay||s.NextFlareAt<0||s.FlareUntil<0||s.Flares<0||new[]{s.RaidIntensity,s.Scarcity,s.InstabilitySetting,s.Disease,s.Stress}.Any(v=>v is <0 or >100)||s.NextIncidentAt<0||s.Incidents<0||s.DirectorStatus==null||s.DirectorStatus.Length>512||s.BaseClimate==null||s.Forecasts==null||s.Refuges==null||s.Projects==null||s.Patrons==null||s.Claims==null||s.History==null||s.Evacuees==null||s.PreservedKnowledge==null||s.Forecasts.Count>32||s.History.Count>64||s.Patrons.Count>6||s.Claims.Count>6||s.Finale!=""&&!FinaleIds.Contains(s.Finale)||s.CompletedAt<0||s.CompletedAt>Tick)throw new InvalidDataException("Invalid solar campaign state.");if(!s.Enabled)return;
  if(!Region.Enabled||!Society.Enabled||s.BaseClimate.Count!=144||s.BaseClimate.Any(k=>k.Key is <0 or >=144||k.Value is < -10 or >49)||s.Refuges.Count!=6||s.Refuges.Select(r=>r.FactionId).Distinct().Count()!=6||s.Projects.Count!=5||s.Projects.Select(p=>p.Id).Distinct().Count()!=5)throw new InvalidDataException("Invalid campaign geography/projects.");
  bool Faction(long id)=>Region.Factions.Any(f=>f.Id==id);var ids=new HashSet<long>();void Id(long id){if(id<1||id>=s.NextId||!ids.Add(id))throw new InvalidDataException("Invalid/duplicate campaign ID.");}
  foreach(var f in s.Forecasts){Id(f.Id);if(f.Kind is not ("Season" or "Flare")||f.IssuedAt<0||f.IssuedAt>Tick||f.DueAt<f.IssuedAt||f.Stage is <0 or >4||f.Text==null||f.Text.Length>512)throw new InvalidDataException("Invalid solar forecast.");}
  foreach(var r in s.Refuges)if(!Faction(r.FactionId)||r.Level is <0 or >3||r.PartsSpent<0||r.WoodSpent<0||r.BrassSpent<0||r.Migrants<0)throw new InvalidDataException("Invalid reserve-funded refuge.");
  foreach(var p in s.Projects)if(!FinaleIds.Contains(p.Id)||p.HostId<0||p.HostId>=NextEntityId||p.WorkerId<0||p.WorkerId>=NextEntityId||p.Phase is <0 or >3||p.Work is <0 or >90||p.Completed!=(p.Phase==3)||p.Completed&&p.Active||p.Active&&(Find(p.HostId)==null||!Colony.People.ContainsKey(p.WorkerId))||p.Status==null||p.Status.Length>512||p.Spent==null||p.Spent.Any(k=>!d.Entities.ContainsKey(k.Key)||k.Value is <0 or >10000))throw new InvalidDataException("Invalid finale project.");
  if(s.Projects.Count(p=>p.Completed)>1||s.Finale!=""&&!s.Projects.Any(p=>p.Id==s.Finale&&p.Completed)||s.SunRestored!=(s.Finale=="Sun")||s.Evacuees.Any(id=>!Colony.People.ContainsKey(id)||Body(id) is not {Dead:false})||s.Evacuees.Count>0&&s.Finale!="Vessel")throw new InvalidDataException("Invalid campaign outcome/custody.");
  foreach(var p in s.Patrons){Id(p.Id);if(!Faction(p.FactionId)||p.Demand is not ("Open access" or "Supplies")||p.DueAt<0||p.BaselineSessions<0||p.Payments<0||p.Result==null||p.Result.Length>512)throw new InvalidDataException("Invalid patron title/obligation.");}if(s.Patrons.Select(p=>p.FactionId).Distinct().Count()!=s.Patrons.Count)throw new InvalidDataException("Duplicate patron compact.");
  foreach(var c in s.Claims){Id(c.Id);if(!Faction(c.FactionId)||!Region.Sites.Any(site=>site.Id==c.SiteId)||c.State is not ("Offered" or "Shared" or "Disputed")||c.DueAt<0||c.Result==null||c.Result.Length>512)throw new InvalidDataException("Invalid sanctuary claim.");}
  foreach(var incident in s.History){Id(incident.Id);if(incident.Tick<0||incident.Tick>Tick||incident.FactionId!=0&&!Faction(incident.FactionId)||incident.Kind==null||incident.Cause==null||incident.Cause.Length>512||incident.Result==null||incident.Result.Length>512)throw new InvalidDataException("Invalid causal director incident.");}
  if(s.PreservedKnowledge.Any(k=>!d.Document.Formulae.Any(f=>f.Id==k)&&!d.Document.Recipes.Any(r=>r.Id==k))||s.PreservedKnowledge.Distinct().Count()!=s.PreservedKnowledge.Count)throw new InvalidDataException("Invalid preserved campaign knowledge.");
 }
}
